// ═══ BLOCKING vs NON-BLOCKING methods ═══
BlockingQueue<String> queue = new LinkedBlockingQueue<>(100);  // bounded: max 100

// BLOCKING (waits):
queue.put("TXN-001");      // blocks if full (waits for space)
String txn = queue.take();  // blocks if empty (waits for element)

// TIMED BLOCKING (waits with timeout):
queue.offer("TXN-002", 5, TimeUnit.SECONDS);  // waits up to 5s, returns false if timeout
String item = queue.poll(5, TimeUnit.SECONDS); // waits up to 5s, returns null if timeout

// NON-BLOCKING (returns immediately):
queue.offer("TXN-003");    // returns false if full (no wait)
String polled = queue.poll(); // returns null if empty (no wait)

// ═══ INTERNAL STRUCTURE ═══
// Two locks: putLock (for tail/producers), takeLock (for head/consumers)
// → producers and consumers don't block EACH OTHER!
// → much better throughput than single-lock Vector/synchronizedList
//
// AtomicInteger count — tracks size without holding both locks
// Condition notEmpty — signals consumer when element added
// Condition notFull  — signals producer when element removed

// ═══ BOUNDED vs UNBOUNDED ═══
// Bounded (recommended): new LinkedBlockingQueue<>(1000)
//   put() blocks when count == 1000 → back-pressure! Producer slows down.
//   Prevents OOM: producer can't overwhelm consumer.

// Unbounded (dangerous): new LinkedBlockingQueue<>()
//   Capacity = Integer.MAX_VALUE — effectively unlimited
//   put() NEVER blocks! If producer is faster → queue grows → OOM!
//   ThreadPoolExecutor with unbounded queue: tasks pile up → OOM crash!

// ═══ vs OTHER BlockingQueues ═══
// LinkedBlockingQueue: linked nodes, two locks, bounded/unbounded
// ArrayBlockingQueue:  array-based, ONE lock, always bounded, fair option
// PriorityBlockingQueue: priority heap, unbounded, no FIFO
// SynchronousQueue: capacity 0! put() blocks until take() — direct handoff
// LinkedTransferQueue: similar to SynchronousQueue but with queue fallback

// ═══ USED IN ThreadPoolExecutor ═══
// new ThreadPoolExecutor(core, max, keepAlive, unit,
//     new LinkedBlockingQueue<>(1000));  // bounded! Back-pressure.
// Executors.newFixedThreadPool(n) uses UNBOUNDED queue → dangerous!
