package com.bank.blocking;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.assertj.core.api.Assertions.*;

class LinkedBlockingQueueTest {

    // ═══ put/take — blocking producer-consumer ═══
    @Test
    void putTake_producerConsumer() throws InterruptedException {
        BlockingQueue<String> queue = new LinkedBlockingQueue<>(5);
        AtomicInteger consumed = new AtomicInteger(0);

        // Producer thread:
        Thread producer = new Thread(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    queue.put("TXN-" + i);  // blocks if full!
                }
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });

        // Consumer thread:
        Thread consumer = new Thread(() -> {
            try {
                for (int i = 0; i < 10; i++) {
                    String txn = queue.take();  // blocks if empty!
                    consumed.incrementAndGet();
                }
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });

        producer.start();
        consumer.start();
        producer.join(5000);
        consumer.join(5000);

        assertThat(consumed.get()).isEqualTo(10);  // all 10 consumed!
    }

    // ═══ Bounded: offer returns false when full ═══
    @Test
    void bounded_offerReturnsFalse() {
        BlockingQueue<String> queue = new LinkedBlockingQueue<>(2);
        assertThat(queue.offer("A")).isTrue();
        assertThat(queue.offer("B")).isTrue();
        assertThat(queue.offer("C")).isFalse();  // full! Returns false immediately.
        assertThat(queue).hasSize(2);
    }

    // ═══ poll with timeout ═══
    @Test
    void poll_withTimeout() throws InterruptedException {
        BlockingQueue<String> queue = new LinkedBlockingQueue<>();
        // Empty queue — poll waits 100ms then returns null:
        String result = queue.poll(100, TimeUnit.MILLISECONDS);
        assertThat(result).isNull();
    }

    // ═══ FIFO order ═══
    @Test
    void fifo_order() throws InterruptedException {
        BlockingQueue<String> queue = new LinkedBlockingQueue<>();
        queue.put("FIRST");
        queue.put("SECOND");
        queue.put("THIRD");

        assertThat(queue.take()).isEqualTo("FIRST");   // FIFO!
        assertThat(queue.take()).isEqualTo("SECOND");
        assertThat(queue.take()).isEqualTo("THIRD");
    }

    // ═══ remainingCapacity ═══
    @Test
    void remainingCapacity() {
        BlockingQueue<String> queue = new LinkedBlockingQueue<>(100);
        queue.offer("A");
        queue.offer("B");
        assertThat(queue.remainingCapacity()).isEqualTo(98);
        assertThat(queue.size()).isEqualTo(2);
    }
}
