class TradeQueue {
  // BOUNDED — back-pressure prevents OOM
  BlockingQueue<Trade> q = new LinkedBlockingQueue<>(50_000);

  void produce(Trade t) throws InterruptedException {
    q.put(t);                 // blocks if full
  }
  Trade consume() throws InterruptedException {
    return q.take();          // blocks if empty
  }
  // internals: two locks + two conditions
  //   putLock + notFull   (producers)
  //   takeLock + notEmpty (consumers)
  //   count = AtomicInteger  (shared across locks)
  // non-blocking: offer()→false full, poll()→null empty
  // timed:        offer(t,500,MS), poll(500,MS)
}
